'use strict';
(async()=>{const status=document.getElementById('status');try{const id=new URLSearchParams(location.search).get('id');if(!/^[0-9a-f]{32}$/.test(id||''))throw Error('全景编号无效');const view=new WYCPanoramaViewer(document.getElementById('view'),v=>{status.textContent=`历史全景 · 方向 ${v.yaw.toFixed(0)}° · 俯仰 ${v.pitch.toFixed(0)}° · 视场 ${v.fov.toFixed(0)}°`;document.getElementById('fov').value=v.fov;});const img=new Image();img.src='/api/panoramas/'+id+'.jpg';await img.decode();view.image(img);const map=document.getElementById('map');map.getContext('2d').drawImage(img,0,0,map.width,map.height);let dragging=false;const choose=e=>{const r=map.getBoundingClientRect();view.set((e.clientX-r.left)/r.width*360-180);};map.onpointerdown=e=>{dragging=true;map.setPointerCapture(e.pointerId);choose(e);};map.onpointermove=e=>{if(dragging)choose(e);};map.onpointerup=map.onpointercancel=()=>dragging=false;document.getElementById('fov').oninput=e=>{view.fov=Number(e.target.value);view.render();};}catch(e){status.textContent=e.message;}})();
